import {assert} from './generation-purge-assert.mjs';

const cases=[],test=(name,fn)=>{if(typeof name!=='string'||typeof fn!=='function')throw Error('native registration');cases.push({name,fn});};
let sequence=0;const repositories=[],ownedNames=new Set(),factoryNames=new WeakMap();
function nativeFactory(){const cap=Object.freeze({});factoryNames.set(cap,new Map());return cap;}
function nativeOptions(options){const names=factoryNames.get(options?.indexedDB);if(!names||typeof options.name!=='string')throw Error('native factory binding');let name=names.get(options.name);if(!name){name='paia-native-phased-copy-retirement-matrix-'+(++sequence)+'-'+options.name;names.set(options.name,name);ownedNames.add(name);}return {...options,indexedDB,name};}
function nativeStore(storage,options){const store=new LibraryDocumentsStore(storage,nativeOptions(options));repositories.push(store.repository);return store;}
function nativeRepository(storage,options){const repository=new ArchiveRepository(storage,nativeOptions(options));repositories.push(repository);return repository;}



export const local = () => { const data = {}; return {async get(k) {return {[k]:structuredClone(data[k])};}, async set(v) {Object.assign(data,structuredClone(v));}}; };
export const capture = (epoch, id = 'm1-synthetic-message-001', text = 'Synthetic explicit working input') => ({epoch,adapterVersion:'0.3.0',chat:{id:'m1-synthetic-chat',url:'https://chatgpt.com/c/m1-synthetic-chat',title:'Synthetic chat'},messages:[{sourceMessageId:id,pageOrder:1,originalText:text}]});
export async function inputEdit(s,id,changes) {const b=await s.input(id);return s.editDocument({operationId:crypto.randomUUID(),documentId:b.documentId,blocks:[{id,expectedRevision:b.revision,libraryText:b.libraryText,note:b.note,excluded:b.excluded,...changes}]});}
export async function derived(s,ids,extra={}) {const evidence=await s.evidenceFor(ids.map(inputId=>({inputId,role:'primary',selectedFields:['body']})));return s.createEntry({operationId:crypto.randomUUID(),actor:'ai',body:'Synthetic conclusion',type:'judgment',formation:ids.length>1?'synthesized':'explicit',evidence,generator:{providerId:'fixture',providerVersion:'1',modelVersion:'deterministic-1',taskSchemaVersion:1,promptTemplateVersion:1,policyVersion:1},...extra});}



import {ArchiveRepository} from '../core/idb-repository.js';
import {LibraryDocumentsStore} from '../core/library-documents-store.js';

import {BrowserNativeSyncCore} from '../core/browser-native-sync/core.js';
import {HumanLibrarySyncJournal} from '../core/browser-native-sync/human-library-journal.js';
import {buildCheckpoint,StagedSyncRestore} from '../core/browser-native-sync/checkpoints.js';
import {CanonicalGenerationPublication} from '../core/browser-native-sync/canonical-generation-publication.js';
import {CanonicalGenerationCheckpointStage,readCanonicalPhasedHumanProof} from '../core/browser-native-sync/canonical-generation-checkpoint-stage.js';
import {CanonicalGenerationPhasedHumanRestore,completeOriginalPhasedHumanPublication} from '../core/browser-native-sync/canonical-generation-phased-human.js';
import {CANONICAL_PHASED_TASK,GENERATION_TASK_LIMITS,readOriginalGenerationControlWork,originalGenerationTaskData,originalGenerationTaskStart,originalGenerationTaskReserve,originalGenerationTaskSettle,originalGenerationTaskBurn} from '../core/browser-native-sync/canonical-generation-task-ledger.js';

async function fixture(t,count=1,checkpoint){const factory=nativeFactory(),source=nativeStore(local(),{indexedDB:factory,name:'SYNTHETIC-phased-source'});await source.consent(true);await source.finishFoundation();const sc=new BrowserNativeSyncCore(source.repository,{datasetId:'synthetic_phased',deviceId:'synthetic_source'});source.humanLibraryJournal=new HumanLibrarySyncJournal(sc);for(let i=0;i<count;i++)await source.createEntry({actor:'user',body:'SYNTHETIC original '+i,type:'idea',formation:'explicit',evidence:[],operationId:crypto.randomUUID()});const objects=new Map(),transport={async putImmutable(ref,raw){objects.set(ref.id,raw.slice());},async get(ref){return objects.get(ref.id)?.slice();}},cp=await buildCheckpoint(sc,transport,{grouped:{store:source}}),registry=nativeRepository(local(),{indexedDB:factory,name:'SYNTHETIC-phased-registry'}),publication=new CanonicalGenerationPublication(registry),store=nativeStore(local(),{indexedDB:factory,name:'SYNTHETIC-phased-target'}),handle=await publication.attach(store.repository,{generationId:'synthetic_generation',databaseId:'synthetic_database'});await store.consent(true);await store.finishFoundation();const core=new BrowserNativeSyncCore(store.repository,{datasetId:sc.datasetId,deviceId:'synthetic_receiver',namespace:'synthetic_replay'});store.humanLibraryJournal=new HumanLibrarySyncJournal(core);const stage=new CanonicalGenerationCheckpointStage(publication,handle,{store,core,checkpoint,protectRepository:true});await stage.begin(cp.ref,r=>transport.get(r));t.after(()=>[source.repository,registry,store.repository].forEach(r=>r.db?.close()));return {stage,publication,handle,store,core,cp,transport,registry,factory};}
const PREFIX='canonical-generation:checkpoint:',RETIRE='canonical-generation:copy-retirement:v1';
async function published(t,count=1){const f=await fixture(t,count);await f.stage.stagePhasedHumanCheckpoint(r=>f.transport.get(r));const proof=await f.stage.validatePhasedHumanCheckpoint(),restore=new CanonicalGenerationPhasedHumanRestore(f);for(let i=0;i<count;i++)await restore.step(proof);await restore.preparePublication(proof);const token=await f.publication.sealOriginalPhasedHumanCheckpoint(f.handle,restore,proof);await f.publication.reserve(token,'synthetic_retirement');await f.publication.recover();return f;}
async function snapshot(f){return f.store.repository.transaction(false,async t=>Object.fromEntries(await Promise.all([...t.tx.objectStoreNames].map(async name=>[name,await t.all(name)]))));}
const bodyCopies=id=>id===PREFIX+'state:v1'||/^canonical-generation:checkpoint:(item|page):[0-9]{8}$/.test(id);
const canonical=s=>({...s,meta:s.meta.filter(r=>!bodyCopies(r.id)&&r.id!==RETIRE)});
async function finish(f){for(let i=0;i<20;i++){const r=await f.publication.retireCheckpointCopies(f.handle);if(r.state==='retired')return r;}throw Error('SYNTHETIC unfinished');}
async function roundtrip(t,f){const objects=new Map(),transport={async putImmutable(ref,raw){objects.set(ref.id,raw.slice());},async get(ref){return objects.get(ref.id)?.slice();}},cp=await buildCheckpoint(f.core,transport,{grouped:{store:f.store}}),store=nativeStore(local(),{indexedDB:nativeFactory(),name:'SYNTHETIC-retirement-cold-C'});t.after(()=>store.repository.db?.close());await store.consent(true);await store.finishFoundation();const core=new BrowserNativeSyncCore(store.repository,{datasetId:f.core.datasetId,deviceId:'synthetic_cold_c'}),restore=new StagedSyncRestore(core,{grouped:{store}});await restore.stageCheckpoint(cp.ref,r=>transport.get(r));await restore.activate();assert.deepEqual((await store.repository.transaction(false,t=>t.all('thoughts'),['thoughts'])).map(r=>r.body),(await f.store.repository.transaction(false,t=>t.all('thoughts'),['thoughts'])).map(r=>r.body));}
test('phased retirement removes only checkpoint body copies and preserves export and audit controls',async t=>{const f=await published(t),before=await snapshot(f);assert.equal((await finish(f)).state,'retired');const after=await snapshot(f);assert.equal(after.meta.filter(r=>bodyCopies(r.id)).length,0);assert.deepEqual(canonical(after),canonical(before));assert.equal(after.meta.find(r=>r.id===CANONICAL_PHASED_TASK).phase,'verified');await roundtrip(t,f);assert.equal((await finish(f)).state,'retired');assert.deepEqual(await snapshot(f),after);});
async function raw(f,fn){await new Promise((resolve,reject)=>{const tx=f.store.repository.db.transaction(['meta'],'readwrite');fn(tx.objectStore('meta'));tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);tx.onerror=()=>{};});}
test('phased retirement bounded page survives actual store and registry close then preserves original edit',async t=>{const f=await published(t,6),before=await snapshot(f),first=await f.publication.retireCheckpointCopies(f.handle);assert.equal(first.state,'retiring');assert.equal(first.itemsRemoved,32);await f.store.repository.close();await f.registry.close();const store=nativeStore(f.store.local,{indexedDB:f.factory,name:'SYNTHETIC-phased-target'}),registry=nativeRepository(local(),{indexedDB:f.factory,name:'SYNTHETIC-phased-registry'}),publication=new CanonicalGenerationPublication(registry),handle=await publication.attach(store.repository,{generationId:'synthetic_generation',databaseId:'synthetic_database'});t.after(()=>[store.repository,registry].forEach(r=>r.db?.close()));Object.assign(f,{store,registry,publication,handle});assert.equal((await finish(f)).state,'retired');assert.deepEqual(canonical(await snapshot(f)),canonical(before));await publication.bindOriginalActiveStore(handle,store);const entry=(await store.repository.transaction(false,t=>t.all('thoughts'),['thoughts']))[0];await store.editEntry({id:entry.id,expectedRevision:entry.revision,changes:{note:'SYNTHETIC after retirement'},operationId:crypto.randomUUID()});assert.equal((await store.entry(entry.id)).note,'SYNTHETIC after retirement');});
for(const kind of ['unknown','missing-item','missing-validation','pending-task','foreign-task','validation-chain','receipt-extra','progress'])test('phased retirement refuses '+kind+' with complete rollback',async t=>{const f=await published(t);await raw(f,s=>{if(kind==='unknown')s.put({id:PREFIX+'unknown',body:'SYNTHETIC'});else if(kind==='missing-item')s.delete(PREFIX+'item:00000000');else if(kind==='missing-validation')s.delete(PREFIX+'validated-page:00000000');else if(kind==='progress')s.put({id:RETIRE,version:2,phase:'retired'});else{const id=kind==='validation-chain'?PREFIX+'validated-task:v1':kind==='receipt-extra'?PREFIX+'validated-page:00000000':CANONICAL_PHASED_TASK,r=s.get(id);r.onsuccess=()=>s.put({...r.result,...(kind==='pending-task'?{phase:'applying'}:kind==='foreign-task'?{identity:{...r.result.identity,manifestId:'f'.repeat(64)}}:kind==='validation-chain'?{pageChain:'f'.repeat(64)}:{extra:'SYNTHETIC'})});}});const before=await snapshot(f);await assert.rejects(f.publication.retireCheckpointCopies(f.handle));assert.deepEqual(await snapshot(f),before);});
for(const kind of ['ledger','new-copy'])test('phased retirement terminal fence refuses late '+kind+' and rolls back deletions',async t=>{const f=await published(t),before=await snapshot(f),task=before.meta.find(r=>r.id===CANONICAL_PHASED_TASK),proto=Object.getPrototypeOf(f.store.repository.db.transaction(['meta'],'readonly').objectStore('meta')),original=proto.put;let injected=0;proto.put=function(row,...args){const result=original.call(this,row,...args);if(this.transaction.db.name===f.store.repository.name&&row?.id===RETIRE){injected++;original.call(this,kind==='ledger'?{...task,burned:task.burned+1}:{id:PREFIX+'unexpected',body:'SYNTHETIC late'});}return result;};try{await assert.rejects(f.publication.retireCheckpointCopies(f.handle));}finally{proto.put=original;}assert.equal(injected,1);assert.deepEqual(await snapshot(f),before);});
test('phased retirement pins audit controls across cleanup calls',async t=>{const f=await published(t,6);await f.publication.retireCheckpointCopies(f.handle);await raw(f,s=>{const r=s.get(CANONICAL_PHASED_TASK);r.onsuccess=()=>s.put({...r.result,burned:r.result.burned+1});});const before=await snapshot(f);await assert.rejects(f.publication.retireCheckpointCopies(f.handle));assert.deepEqual(await snapshot(f),before);});

const previous=globalThis.__bnsNative;
globalThis.__bnsNative={...previous,async run(command,...args){
 if(command!=="phased-copy-retirement-matrix")return previous.run(command,...args);
 const passed=[];
 const selected=cases;if(selected.length!==13)throw Error('native selected count');
 for(const item of selected){const after=[];let failure;
  try{await item.fn({after(fn){if(typeof fn!=='function')throw Error('native after');after.push(fn);}});passed.push(item.name);}
  catch(error){failure=Error(item.name+': '+error.stack);}
  finally{
   for(const fn of after.reverse())try{await fn();}catch(error){failure??=error;}
   for(const repository of repositories.splice(0))try{await repository.close();}catch(error){failure??=error;}
   for(const name of ownedNames){try{await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(name);request.onsuccess=resolve;request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('native cleanup blocked'));});}catch(error){failure??=error;}}ownedNames.clear();
  }
  if(failure)throw failure;
 }
 return passed;
}};
